result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "engine.py", "content": """"Generic table-driven clinical scoring engine.

A score is defined purely as data:

    rules = [
        {
            "name": "age_ge_75",
            "points": 2,
            "when": {"field": "age", "op": "ge", "value": 75},
        },
        ...
    ]

Optional rule groups cap the total contribution of a set of mutually
exclusive criteria (e.g. CURB-65's blood-pressure criterion counts at
most once whether systolic or diastolic triggers it):

    groups = {"blood_pressure": {"max": 1}}

and individual rules opt into a group via `"group": "blood_pressure"`.

There are no score-specific code paths anywhere: adding a new clinical
score means adding a JSON file.
"""

from __future__ import annotations

import json
import numbers
from pathlib import Path


class MissingFieldError(KeyError):
    """Raised when a record lacks a field referenced by a rule."""

    def __init__(self, field: str):
        super().__init__(field)
        self.field = field


def _require_number(value, op):
    if not isinstance(value, numbers.Real) or isinstance(value, bool):
        raise TypeError(f"operator {op!r} requires a numeric field value, got {value!r}")


def _match(op: str, actual, expected):
    """Evaluate one condition. Returns True iff the rule fires."""
    if op == "eq":
        return bool(actual == expected) and isinstance(actual, bool) == isinstance(expected, bool)
    if op == "ge":
        _require_number(actual, op)
        return actual >= expected
    if op == "gt":
        _require_number(actual, op)
        return actual > expected
    if op == "le":
        _require_number(actual, op)
        return actual <= expected
    if op == "lt":
        _require_number(actual, op)
        return actual < expected
    if op == "between":
        _require_number(actual, op)
        lo, hi = expected
        return lo <= actual <= hi
    raise ValueError(f"unknown operator: {op!r}")


_OPS = frozenset({"eq", "ge", "gt", "lt", "le", "between"})


class ScoreEngine:
    """Evaluate a patient record against a table of rules."""

    def __init__(self, rules, groups=None, name="score"):
        self.name = name
        self.rules = list(rules)
        self.groups = dict(groups or {})
        self._validate()

    def _validate(self):
        for i, rule in enumerate(self.rules):
            try:
                rule["name"], rule["points"], rule["when"]
                when = rule["when"]
                when["field"], when["op"], when["value"]
            except (KeyError, TypeError) as exc:
                raise ValueError(f"malformed rule at index {i}: {rule!r}") from exc
            if when["op"] not in _OPS:
                raise ValueError(
                    f"rule {rule['name']!r}: unknown operator {when['op']!r}"
                )
            if when["op"] == "between" and (
                not isinstance(when["value"], (list, tuple)) or len(when["value"]) != 2
            ):
                raise ValueError(
                    f"rule {rule['name']!r}: 'between' requires [lo, hi]"
                )
            group = rule.get("group")
            if group is not None and group not in self.groups:
                raise ValueError(
                    f"rule {rule['name']!r} references undefined group {group!r}"
                )

    def evaluate(self, record):
        """Return {"total": int, "fired": [rule names]} for a patient record.

        Raises MissingFieldError if any field referenced by any rule is
        absent from the record. Group-capped rules stop firing (without
        error) once the group's budget is exhausted.
        """
        total = 0
        fired = []
        spent = {g: 0 for g in self.groups}

        for rule in self.rules:
            when = rule["when"]
            field = when["field"]
            if field not in record:
                raise MissingFieldError(field)
            if not _match(when["op"], record[field], when["value"]):
                continue

            points = rule["points"]
            group = rule.get("group")
            if group is not None:
                remaining = self.groups[group]["max"] - spent[group]
                if remaining <= 0:
                    continue  # group budget exhausted: rule matches but does not fire
                points = min(points, remaining)
                spent[group] += points

            total += points
            fired.append(rule["name"])

        return {"total": total, "fired": fired}


def load_score(path):
    """Load a score definition from a JSON file -> ScoreEngine.

    Accepted schema:
        {
          "name":   str,
          "groups": {group_name: {"max": int}},   # optional
          "rules":  [ {name, points, when[, group]}, ... ]
        }
    """
    path = Path(path)
    with path.open(encoding="utf-8") as fh:
        spec = json.load(fh)
    return ScoreEngine(spec["rules"], spec.get("groups"), name=spec.get("name", path.stem))
