import pytest

from engine import MissingFieldError, ScoreEngine


def make(field, op, value, points=1):
    return ScoreEngine(
        [{"name": "r", "points": points,
          "when": {"field": field, "op": op, "value": value}}]
    )


class TestEq:
    def test_true_fires(self):
        assert make("f", "eq", True).evaluate({"f": True})["total"] == 1

    def test_false_does_not_fire(self):
        assert make("f", "eq", True).evaluate({"f": False})["total"] == 0

    def test_bool_is_not_number(self):
        # eq(True) must not match numeric 1
        assert make("f", "eq", True).evaluate({"f": 1})["total"] == 0

    def test_string_equality(self):
        assert make("f", "eq", "yes").evaluate({"f": "yes"})["total"] == 1


class TestComparisons:
    @pytest.mark.parametrize("op,value,actual,fires", [
        ("ge", 75, 75, True), ("ge", 75, 74.9, False),
        ("gt", 7, 7.1, True), ("gt", 7, 7, False),
        ("le", 60, 60, True), ("le", 60, 60.1, False),
        ("lt", 90, 89.99, True), ("lt", 90, 90, False),
    ])
    def test_boundaries(self, op, value, actual, fires):
        got = make("f", op, value).evaluate({"f": actual})["total"]
        assert got == (1 if fires else 0)

    def test_non_numeric_rejected_for_ordering_ops(self):
        with pytest.raises(TypeError):
            make("f", "ge", 5).evaluate({"f": "old"})


class TestBetween:
    def test_inclusive_bounds(self):
        eng = make("age", "between", [65, 74])
        for age in (65, 70, 74):
            assert eng.evaluate({"age": age})["total"] == 1
        for age in (64, 64.999, 75):
            assert eng.evaluate({"age": age})["total"] == 0

    def test_points_passed_through(self):
        assert make("a", "between", [1, 10], points=3).evaluate({"a": 5})["total"] == 3


class TestEvaluateShape:
    def test_fired_lists_names_in_rule_order(self):
        eng = ScoreEngine([
            {"name": "b", "points": 2, "when": {"field": "x", "op": "ge", "value": 1}},
            {"name": "a", "points": 1, "when": {"field": "y", "op": "eq", "value": True}},
            {"name": "n", "points": 1, "when": {"field": "z", "op": "eq", "value": True}},
        ])
        out = eng.evaluate({"x": 5, "y": True, "z": False})
        assert out == {"total": 3, "fired": ["b", "a"]}

    def test_empty_rules(self):
        assert ScoreEngine([]).evaluate({}) == {"total": 0, "fired": []}


class TestMissingFields:
    def test_missing_field_raises(self):
        with pytest.raises(MissingFieldError) as exc:
            make("urea", "gt", 7).evaluate({"rr": 20})
        assert exc.value.field == "urea"

    def test_all_fields_required_even_if_earlier_rules_fire(self):
        eng = ScoreEngine([
            {"name": "a", "points": 1, "when": {"field": "x", "op": "eq", "value": True}},
            {"name": "b", "points": 1, "when": {"field": "missing", "op": "eq", "value": True}},
        ])
        with pytest.raises(MissingFieldError):
            eng.evaluate({"x": True})


class TestRuleGroups:
    def rules(self):
        return [
            {"name": "sbp_low", "points": 1, "group": "bp",
             "when": {"field": "sbp", "op": "lt", "value": 90}},
            {"name": "dbp_low", "points": 1, "group": "bp",
             "when": {"field": "dbp", "op": "le", "value": 60}},
        ]

    def test_only_one_group_member_counts(self):
        eng = ScoreEngine(self.rules(), {"bp": {"max": 1}})
        out = eng.evaluate({"sbp": 80, "dbp": 50})
        assert out == {"total": 1, "fired": ["sbp_low"]}  # first match wins the budget

    def test_second_member_alone_still_fires(self):
        eng = ScoreEngine(self.rules(), {"bp": {"max": 1}})
        assert eng.evaluate({"sbp": 120, "dbp": 55}) == {"total": 1, "fired": ["dbp_low"]}

    def test_uncapped_group_sums(self):
        eng = ScoreEngine(self.rules(), {"bp": {"max": 2}})
        assert eng.evaluate({"sbp": 80, "dbp": 50})["total"] == 2

    def test_partial_budget_caps_points_not_membership(self):
        eng = ScoreEngine(
            [{"name": "big", "points": 2, "group": "g",
              "when": {"field": "x", "op": "eq", "value": True}},
             {"name": "small", "points": 1, "group": "g",
              "when": {"field": "y", "op": "eq", "value": True}}],
            {"g": {"max": 3}},
        )
        out = eng.evaluate({"x": True, "y": True})
        assert out == {"total": 3, "fired": ["big", "small"]}


class TestValidation:
    def test_unknown_op_rejected_up_front(self):
        with pytest.raises(ValueError, match="operator"):
            ScoreEngine([{"name": "r", "points": 1,
                          "when": {"field": "f", "op": "~=", "value": 1}}])

    def test_between_needs_pair(self):
        with pytest.raises(ValueError, match="between"):
            ScoreEngine([{"name": "r", "points": 1,
                          "when": {"field": "f", "op": "between", "value": [1]}}])

    def test_undefined_group_rejected(self):
        with pytest.raises(ValueError, match="group"):
            ScoreEngine([{"name": "r", "points": 1, "group": "nope",
                          "when": {"field": "f", "op": "eq", "value": True}}])
